def owner_names(owner: str | None) -> list[str]:
    if not owner:
        return []
    normalized = owner.replace(",", "+")
    return [part.strip() for part in normalized.split("+") if part.strip()]


def read_json(path: pathlib.Path) -> dict:
    with path.open("r", encoding="utf-8") as handle:
        return json.load(handle)


def read_tsv(path: pathlib.Path) -> list[dict[str, str]]:
    import csv

    with path.open("r", encoding="utf-8", newline="") as handle:
        return list(csv.DictReader(handle, delimiter="\t", quoting=csv.QUOTE_NONE))


def rel_path(path: pathlib.Path) -> str:
    return path.relative_to(ROOT).as_posix()


def percent_string(numerator: int, denominator: int) -> str:
    if denominator == 0:
        return "NA"
    return f"{(100 * numerator / denominator):.1f}%"


def text_line_number(text: str, index: int) -> int:
    return text.count("\n", 0, index) + 1


def local_documenter_claim_paths() -> list[pathlib.Path]:
    """Return local Documenter.jl claim files if this repo ever grows them."""

    paths: list[pathlib.Path] = []
    docs_src = ROOT / "docs" / "src"
    if docs_src.exists():
        paths.extend(path for path in docs_src.rglob("*") if path.is_file())
    for name in ("make.jl", "Documenter.toml", "Project.toml"):
        path = ROOT / "docs" / name
        if path.exists():
            paths.append(path)
    return sorted(set(paths))


def public_claim_scan_paths() -> list[pathlib.Path]:
    paths = list(PUBLIC_CLAIM_SCAN_FILES)
    paths.extend(sorted((ROOT / "vignettes").glob("*.Rmd")))
    paths.extend(local_documenter_claim_paths())
    return [path for path in sorted(set(paths)) if path.exists()]


def matrix_row_count_from_design(path: pathlib.Path) -> int:
    text = path.read_text(encoding="utf-8")
    match = re.search(r"## Finish Matrix\n(?P<table>.*?)\n## Issue-Led", text, re.S)
    if not match:
        return -1
    rows = []
    for line in match.group("table").splitlines():
        line = line.strip()
        if not line.startswith("|"):
            continue
        if set(line.replace("|", "").replace(" ", "")) == {"-"}:
            continue
        if line.startswith("| Area "):
            continue
        rows.append(line)
    return len(rows)


def evidence_reference_exists(reference: str) -> bool:
    if reference in {"", "planned", "none"}:
        return False
    if re.match(r"^https://github\.com/[^/]+/[^/]+/(issues|pull)/[0-9]+", reference):
        return True
    path = pathlib.Path(reference)
    if path.is_absolute():
        return path.exists()
    return (ROOT / reference).exists()


def _is_finite_number(value: str | None) -> bool:
    try:
        return math.isfinite(float(value or ""))
    except ValueError:
        return False


def expect_float_close(
    errors: list[str],
    row_id: str,
    field: str,
    actual: str | None,
    expected: float,
    tolerance: float = 1e-12,
) -> None:
    try:
        value = float(actual or "")
    except ValueError:
        errors.append(f"{row_id}: {field} must be numeric close to {expected!r}")
        return
    if abs(value - expected) > tolerance:
        errors.append(f"{row_id}: {field} must be close to {expected!r}")


def member_list(value: str) -> list[str]:
    if value in {"", "none"}:
        return []
    return [part.strip() for part in value.split(";") if part.strip()]


def slug(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "_", value.lower()).strip("_")


def qseries_v1_release_classification(row: dict[str, str]) -> dict[str, str]:
    exact_ir = (
        row.get("family_class") == "gaussian"
        and row.get("interval_status") == "inference_ready"
        and row.get("coverage_status") == "inference_ready"
    )
    if exact_ir:
        return {
            "v1_track": "gaussian_inference_anchor",
            "v1_priority": "P1",
            "v1_release_role": (
                "Exact Gaussian inference-ready anchor for v1.0; keep row-local."
            ),
            "post_v1_gate": (
                "Post-v1.0 supported-tier stress review before public support wording."
            ),
            "claim_boundary": (
                "Exact inference_ready remains row-local; no neighbouring row, q4/q8 "
                "route, supported claim, REML, AI-REML, new coverage, or public "
                "support is promoted by this ledger."
            ),
        }
    if row.get("family_class") == "gaussian":
        if row.get("fit_status") in {"point_fit", "supported", "diagnostic_only"}:
            return {
                "v1_track": "gaussian_basic_working",
                "v1_priority": "P2",
                "v1_release_role": (
                    "Implemented/basic-working Gaussian candidate for the v1.0 surface."
                ),
                "post_v1_gate": (
                    "Row-specific retained-denominator interval and coverage review "
                    "if this row is promoted beyond basic working."
                ),
                "claim_boundary": (
                    "Basic-working is not interval_status, coverage_status, "
                    "inference_ready, supported, REML, AI-REML, new coverage, or "
                    "public support."
                ),
            }
        return {
            "v1_track": "gaussian_post_v1_validation",
            "v1_priority": "P4",
            "v1_release_role": (
                "Gaussian row left outside the v1.0 basic-working surface."
            ),
            "post_v1_gate": (
                "Implementation, rejection, or interval route design after the v1.0 cut."
            ),
            "claim_boundary": (
                "Deferred Gaussian validation creates no support-cell promotion, no "
                "inference_ready, no supported claim, no coverage, no REML, no "
                "AI-REML, and no public support."
            ),
        }
    if row.get("family_class") == "non_gaussian" and row.get("fit_status") in {
        "point_fit",
        "diagnostic_only",
    }:
        diagnostic_only = row.get("fit_status") == "diagnostic_only"
        if diagnostic_only:
            return {
                "v1_track": "basic_distribution_recovery",
                "v1_priority": "P3",
                "v1_release_role": (
                    "Basic-distribution diagnostic candidate for v1.0, with "
                    "interval/support deferred."
                ),
                "post_v1_gate": (
                    "Family-specific recovery, interval, coverage, and "
                    "structured-covariance design after v1.0."
                ),
                "claim_boundary": (
                    "Diagnostic-only evidence does not establish point-estimate "
                    "recovery and is not interval evidence, coverage evidence, "
                    "inference_ready, supported, REML, AI-REML, broad "
                    "structured-covariance support, or public support."
                ),
            }
        return {
            "v1_track": "basic_distribution_recovery",
            "v1_priority": "P3",
            "v1_release_role": (
                "Basic-distribution recovery candidate for v1.0, with "
                "interval/support deferred."
            ),
            "post_v1_gate": (
                "Family-specific interval, coverage, and structured-covariance design "
                "after v1.0."
            ),
            "claim_boundary": (
                "Recovery-only evidence is not interval evidence, coverage evidence, "
                "inference_ready, supported, REML, AI-REML, broad "
                "structured-covariance support, or public support."
            ),
        }
    return {
        "v1_track": "basic_distribution_post_v1_design",
        "v1_priority": "P5",
        "v1_release_role": (
            "Non-Gaussian row left outside the v1.0 basic-distribution surface."
        ),
        "post_v1_gate": (
            "Family-specific implementation, rejection, or limitation design after "
            "the v1.0 cut."
        ),
        "claim_boundary": (
            "Deferred family design creates no parser-ready shortcut, no interval "
            "evidence, no coverage, no inference_ready, no supported claim, no REML, "
            "no AI-REML, and no public support."
        ),
    }


